from pypdf import PdfReader
reader=PdfReader('/root/sc100-blank.pdf')
for i,page in enumerate(reader.pages):
    annots=page.get('/Annots')
    if not annots:
        continue
    print('PAGE', i)
    for a in annots:
        obj=a.get_object()
        t=obj.get('/T')
        tu=obj.get('/TU')
        if t:
            print(' ', t, '::', tu)
    print()
